line-danger" data-confirm="Hủy khoản thanh toán?">Hủy</button></form>@endif @endif</td></tr>@empty<tr><td colspan="11"><div class="empty-state">Chưa có khoản thanh toán. Hãy chọn kỳ và bấm “Tính khoản thanh toán”.</div></td></tr>@endforelse</tbody></table></div>@if($payments->hasPages())<div class="card-footer bg-white border-0 p-3">{{ $payments->links() }}</div>@endif</div>
